# SPDX-License-Identifier: Apache-2.0
# Project-RuntimeLock.ps1 - pure helpers that validate a pinned lock and project
# the production (runtime) closure out of the full development lock.
#
# Why this file exists
# --------------------
# backend\requirements.runtime.lock.txt is the ONLY dependency source the
# production install chain is allowed to use (first-run installers on Windows,
# macOS and Linux, the packaged desktop runtime, and the release workflow). It is
# generated by uv from backend\requirements.txt:
#
#   cd backend
#   uv pip compile --universal --python-version 3.11 --generate-hashes \
#       -o requirements.runtime.lock.txt requirements.txt
#
# Regenerating it is the only supported way to change it, and the generator is
# not available on every machine (and never at user time). So the properties that
# matter are re-checked here as plain functions over file *text*:
#
#   * every pin carries at least one --hash=sha256 (pip --require-hashes needs it);
#   * no development tool leaked into the production set;
#   * the lock does not delegate to another requirements file ("-r ..."), which
#     would silently put the resolver back in charge of versions;
#   * the package set equals the runtime closure of backend\requirements.txt, as
#     computed from the "# via" graph of backend\requirements.lock.txt. That last
#     one is the drift guard: it proves the runtime lock is a projection of the
#     same single pin source, without needing uv or the network.
#
# Markers: uv writes ONE universal lock covering every supported platform and
# interpreter, so PEP 508 environment markers are expected and must be preserved
# verbatim (e.g. uvloop on sys_platform != 'win32'). Dropping a marker is a bug;
# the projection below copies lines, it never rewrites them.
#
# Dot-source this file (`. scripts\Project-RuntimeLock.ps1`); it defines functions
# only and emits no output.

# Lock file names, absolute relative to the repository backend directory.
$script:RfRuntimeLockFileName = "requirements.runtime.lock.txt"
$script:RfDevelopmentLockFileName = "requirements.lock.txt"
$script:RfRequirementsFileName = "requirements.txt"

function Get-RuntimeLockFileName {
    # The production lock. Everything that installs dependencies at user time or
    # in a release build must use exactly this file name.
    return $script:RfRuntimeLockFileName
}

function Get-DevelopmentLockFileName {
    # The universal lock over requirements-dev.txt (runtime + dev tooling). Only
    # used to project/verify the runtime closure and to prove the two locks agree.
    return $script:RfDevelopmentLockFileName
}

function Get-RequirementsFileName {
    # The single hand-maintained pin source. Never installed directly by the
    # production chain: it has no hashes, so pip would be free to re-resolve.
    return $script:RfRequirementsFileName
}

function Get-RuntimeLockPath {
    # Single place that decides which lock file the runtime is built from. Every
    # script that needs the lock goes through this, so "which file is the lock"
    # cannot drift between the builder, the packager and the tests.
    #
    # Lives here rather than in PythonRuntimeManifest.ps1: the updater, the
    # process helper and the builder all dot-source THIS file to reach the lock
    # names, and only some of them need the manifest. Keeping the path helper
    # next to the names it composes is what keeps "which files must I dot-source"
    # a one-file answer. (It used to live in the manifest, so
    # Update-ResumeForge.ps1 / ResumeForge.Process.ps1 / Build-PythonRuntime.ps1
    # called an undefined function and the whole launch chain died at first run.)
    param(
        [Parameter(Mandatory = $true)][string]$BackendDirectory
    )

    return (Join-Path $BackendDirectory (Get-RuntimeLockFileName))
}

function ConvertTo-NormalizedPackageName {
    # PEP 503 normalisation (lowercase, runs of -_. collapse to -). Comparison of
    # package names between the two locks must not depend on how uv spelled them.
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )

    return ($Name.ToLowerInvariant() -replace "[-_.]+", "-")
}

function Read-LockTextFile {
    # Reads a lock/requirements file as text without touching the shell encoding.
    # Deliberately byte-exact UTF-8: the locks are pure ASCII by rule, and reading
    # them through Get-Content would normalise line endings on some hosts.
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "lock file not found at '$Path'."
    }
    return [System.Text.Encoding]::UTF8.GetString([System.IO.File]::ReadAllBytes($Path))
}

function Get-LockEntryList {
    # Parses uv lock text into pinned entries. Each entry keeps its raw lines so
    # the caller can re-emit a subset byte-for-byte (hashes and markers included)
    # instead of re-rendering it.
    #
    # Returned objects: Name (normalised), Specifier (version string as written),
    # Marker (text after ';' or ''), Parents (names from the "# via" block) and
    # Lines (raw lines belonging to the entry).
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LockText
    )

    $pinPattern = '^([A-Za-z0-9][A-Za-z0-9._-]*)==([^\s;\\]+)'
    $entries = New-Object System.Collections.Generic.List[object]
    $current = $null
    $parents = New-Object System.Collections.Generic.List[string]
    $inViaBlock = $false

    foreach ($rawLine in ($LockText -split "`n")) {
        $line = $rawLine.TrimEnd("`r")
        $match = [regex]::Match($line, $pinPattern)
        if ($match.Success) {
            if ($null -ne $current) {
                $current.Parents = @($parents)
                $current.Lines = @($current.Lines)
                $entries.Add($current)
            }
            $name = ConvertTo-NormalizedPackageName -Name $match.Groups[1].Value
            $tail = $line.Substring($match.Index + $match.Length)
            $marker = ""
            $semicolon = $tail.IndexOf(";")
            if ($semicolon -ge 0) {
                $marker = $tail.Substring($semicolon + 1).Trim().TrimEnd("\").Trim()
            }
            $current = [pscustomobject]@{
                Name      = $name
                Specifier = $match.Groups[2].Value
                Marker    = $marker
                Parents   = @()
                Lines     = @($line)
            }
            $parents = New-Object System.Collections.Generic.List[string]
            $inViaBlock = $false
            continue
        }

        if ($null -eq $current) { continue }

        $current.Lines = @($current.Lines) + @($line)
        $trimmed = $line.Trim()
        if ($trimmed.StartsWith("# via")) {
            $inViaBlock = $true
            $rest = $trimmed.Substring("# via".Length).Trim()
            if ($rest.Length -gt 0) { $parents.Add($rest) }
            continue
        }
        if ($inViaBlock -and $trimmed.StartsWith("#")) {
            $entryName = $trimmed.TrimStart("#").Trim()
            if ($entryName.Length -gt 0) { $parents.Add($entryName) }
            continue
        }
        if ($trimmed.StartsWith("--hash")) { continue }
        # Anything else (blank line, a new comment) closes the via block.
        $inViaBlock = $false
    }
    if ($null -ne $current) {
        $current.Parents = @($parents)
        $current.Lines = @($current.Lines)
        $entries.Add($current)
    }

    return $entries.ToArray()
}

function Get-RuntimeLockRootNames {
    # Roots = the packages backend\requirements.txt pins directly. Extras are part
    # of the requirement but not of the name (`uvicorn[standard]==0.54.0`), and
    # uv keeps the extras' own dependencies in the lock, so the bare name is what
    # the closure walk needs.
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RequirementsText
    )

    $rootPattern = '^\s*([A-Za-z0-9][A-Za-z0-9._-]*)\s*(\[[^\]]*\])?\s*=='
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($rawLine in ($RequirementsText -split "`n")) {
        $line = $rawLine.TrimEnd("`r")
        if ($line.TrimStart().StartsWith("#")) { continue }
        $match = [regex]::Match($line, $rootPattern)
        if (-not $match.Success) { continue }
        $name = ConvertTo-NormalizedPackageName -Name $match.Groups[1].Value
        if (-not $names.Contains($name)) { $names.Add($name) }
    }
    return $names.ToArray()
}

function Select-RuntimeLockEntries {
    # Projects the production closure out of a full (dev) lock.
    #
    # Walk: start from the roots (requirements.txt pins) and repeatedly pull in any
    # entry that lists an already-kept package in its "# via" block. "# via
    # -r requirements.txt" marks a root, but roots are taken from the requirements
    # file itself: the dev lock's "-r" annotation cannot say *which* file, and
    # requirements-dev.txt has its own direct pins.
    #
    # Order is preserved (the lock's own order), and the entries are returned as
    # parsed so their raw lines -- hashes, markers, via comments -- survive intact.
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LockText,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RequirementsText
    )

    # @() at the call site on purpose: a function that returns an array unwraps a
    # single entry to a scalar and an empty one to $null, and the .Count/.Add
    # handling below must see a real array either way.
    $entries = @(Get-LockEntryList -LockText $LockText)
    $keep = New-Object System.Collections.Generic.HashSet[string]
    foreach ($root in @(Get-RuntimeLockRootNames -RequirementsText $RequirementsText)) {
        [void]$keep.Add($root)
    }

    $changed = $true
    while ($changed) {
        $changed = $false
        foreach ($entry in $entries) {
            if ($keep.Contains($entry.Name)) { continue }
            foreach ($parent in $entry.Parents) {
                $normalized = ConvertTo-NormalizedPackageName -Name $parent
                if ($normalized.StartsWith("-r ")) { continue }
                if ($keep.Contains($normalized)) {
                    [void]$keep.Add($entry.Name)
                    $changed = $true
                    break
                }
            }
        }
    }

    $projected = New-Object System.Collections.Generic.List[object]
    foreach ($entry in $entries) {
        if ($keep.Contains($entry.Name)) { $projected.Add($entry) }
    }
    return $projected.ToArray()
}

function ConvertTo-LockText {
    # Re-emits parsed entries as lock text. Lines are copied, never rebuilt, so a
    # projected lock stays byte-comparable with what uv would produce.
    param(
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Entries
    )

    $builder = New-Object System.Text.StringBuilder
    foreach ($entry in $Entries) {
        foreach ($line in $entry.Lines) {
            [void]$builder.Append($line).Append("`n")
        }
    }
    return $builder.ToString()
}

function Get-RuntimeLockPackageNames {
    # Sorted, normalised package names of a lock -- the comparable form of a lock
    # file. Used by the drift guard to assert "same set, same pins".
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LockText
    )

    $names = New-Object System.Collections.Generic.List[string]
    foreach ($entry in (Get-LockEntryList -LockText $LockText)) {
        $names.Add($entry.Name)
    }
    return @($names | Sort-Object)
}

function Get-LockVersionMap {
    # name -> version for a lock, so a drift check can tell "extra package" from
    # "same package, different version".
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LockText
    )

    $map = @{}
    foreach ($entry in (Get-LockEntryList -LockText $LockText)) {
        $map[$entry.Name] = $entry.Specifier
    }
    return $map
}

function Test-DevToolPackageName {
    # Pattern guard for the one property that must never regress: a production
    # runtime must not carry the test/lint/audit toolchain. Prefix-matched on
    # purpose -- "pytest" has five plugin packages and a bare equality list would
    # go stale the next time one is added. The exhaustive set check is the drift
    # guard (runtime lock == closure of requirements.txt), which needs no list.
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )

    $normalized = ConvertTo-NormalizedPackageName -Name $Name
    $patterns = @(
        '^pytest',
        '^ruff$',
        '^pyright$',
        '^coverage$',
        '^execnet$',
        '^iniconfig$',
        '^pluggy$',
        '^nodeenv$',
        '^pip$',
        '^pip-api$',
        '^pip-audit$',
        '^pip-licenses$',
        '^pip-requirements-parser$',
        '^playwright$',
        '^pyee$'
    )
    foreach ($pattern in $patterns) {
        if ($normalized -match $pattern) { return $true }
    }
    return $false
}

function Get-RuntimeLockProblems {
    # Fail-closed validation of a production lock. Returns a list of human-readable
    # problems; an empty list means usable. Every problem names the offending line
    # so a failure in CI says what to fix.
    #
    # The caller must treat a non-empty result as fatal. There is deliberately no
    # "fall back to requirements.txt" path: an unusable lock means a broken
    # checkout or a bad regeneration, and silently re-resolving top-level pins is
    # exactly the class of failure this guard exists to prevent.
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LockText,
        [switch]$RejectDevTools
    )

    $problems = New-Object System.Collections.Generic.List[string]
    $entries = @(Get-LockEntryList -LockText $LockText)

    if ($entries.Count -eq 0) {
        $problems.Add("the lock contains no pinned 'name==version' entries")
        return $problems.ToArray()
    }

    foreach ($entry in $entries) {
        $hasHash = $false
        foreach ($line in $entry.Lines) {
            if ($line.Trim().StartsWith("--hash=sha256:")) { $hasHash = $true; break }
        }
        if (-not $hasHash) {
            $problems.Add("'$($entry.Name)==$($entry.Specifier)' has no --hash=sha256 line, so pip --require-hashes cannot verify it")
        }
        if ($RejectDevTools -and (Test-DevToolPackageName -Name $entry.Name)) {
            $problems.Add("'$($entry.Name)' is a development tool and must not appear in the production runtime lock")
        }
    }

    # A delegation line ("-r other.txt") would hand version selection back to the
    # resolver while still looking like a lock.
    $delegationPattern = '^\s*(-r|--requirement|-c|--constraint|-e|--editable)\b'
    foreach ($rawLine in ($LockText -split "`n")) {
        if ([regex]::IsMatch($rawLine, $delegationPattern)) {
            $problems.Add("the lock delegates to another requirements file ('$($rawLine.Trim())'); a production lock must list every pin itself")
        }
    }

    # A trailing continuation means the file was truncated mid-entry.
    $lastLine = ($LockText -split "`n" | Where-Object { $_.Trim().Length -gt 0 } | Select-Object -Last 1)
    if ($null -ne $lastLine -and $lastLine.TrimEnd("`r").TrimEnd().EndsWith("\")) {
        $problems.Add("the lock ends with a line continuation ('\'), so it was truncated")
    }

    return $problems.ToArray()
}

function Assert-RuntimeLockUsable {
    # Throws with the full problem list when a production lock may not be installed.
    # Separate from Get-RuntimeLockProblems so tests can assert the exact message
    # class while production still fails loudly.
    param(
        [Parameter(Mandatory = $true)][string]$LockPath
    )

    if (-not (Test-Path -LiteralPath $LockPath -PathType Leaf)) {
        throw ("production dependency lock not found at '$LockPath'. " +
            "It ships with the repository; a checkout without it cannot install the backend. " +
            "Regenerate it with: cd backend; uv pip compile --universal --python-version 3.11 --generate-hashes -o requirements.runtime.lock.txt requirements.txt")
    }

    $text = Read-LockTextFile -Path $LockPath
    $problems = @(Get-RuntimeLockProblems -LockText $text -RejectDevTools)
    if ($problems.Count -gt 0) {
        throw ("production dependency lock '$LockPath' is not usable:`n  - " + ($problems -join "`n  - "))
    }
    return $text
}
